package server

func init() {
	pages["blocks"] = `{{define "content"}}<h1>My blocklist</h1><p>Users on this list cannot exchange data with your routers. You can also block a user from their profile.</p><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>User</th><th>Blocked since</th><th></th></tr></thead><tbody>{{range .Items}}<tr><td><a href="/profiles/{{.BlockedID}}">{{.BlockedEmail}}</a></td><td>{{date .CreatedAt}}</td><td><form method="post" action="/blocks/{{.BlockedID}}/remove"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button class="btn btn-outline-success btn-sm">Unblock</button></form></td></tr>{{else}}<tr><td colspan="3">No blocked users.</td></tr>{{end}}</tbody></table></div>{{end}}`
	pages["admin_blocks"] = `{{define "content"}}<h1>All user blocklists</h1><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Owner</th><th>Blocked user</th><th>Since</th></tr></thead><tbody>{{range .Items}}<tr><td><a href="/profiles/{{.OwnerID}}">{{.OwnerEmail}}</a></td><td><a href="/profiles/{{.BlockedID}}">{{.BlockedEmail}}</a></td><td>{{date .CreatedAt}}</td></tr>{{else}}<tr><td colspan="3">No users are blocked.</td></tr>{{end}}</tbody></table></div>{{end}}`
	pages["delete_account"] = `{{define "content"}}<div class="col-lg-7"><h1>Delete my account</h1><div class="alert alert-danger">This permanently removes your profile, routers, API clients, sessions, logs and blocks. Managed CP addresses are retired and remain reserved.</div><form method="post" action="/settings/delete"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="mb-3"><label class="form-label" for="delete-password">Current password</label><input class="form-control" id="delete-password" type="password" name="password" required></div><div class="mb-3"><label class="form-label" for="delete-confirm">Type DELETE to confirm</label><input class="form-control" id="delete-confirm" name="confirm" autocomplete="off" required></div><button class="btn btn-danger">Delete my account</button> <a class="btn btn-link" href="/settings">Cancel</a></form></div>{{end}}`
	pages["admin_delete_user"] = `{{define "content"}}<div class="col-lg-7"><h1>Delete user</h1><div class="alert alert-danger">Permanently delete <strong>{{.Target.Email}}</strong> and their account data. Their managed CP addresses will be retired and remain reserved.</div><form method="post" action="/admin/users/{{.Target.ID}}/delete"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="mb-3"><label class="form-label" for="admin-delete-password">Your admin password</label><input class="form-control" id="admin-delete-password" type="password" name="password" required></div><div class="mb-3"><label class="form-label" for="admin-delete-confirm">Type DELETE to confirm</label><input class="form-control" id="admin-delete-confirm" name="confirm" autocomplete="off" required></div><button class="btn btn-danger">Delete user</button> <a class="btn btn-link" href="/admin/users">Cancel</a></form></div>{{end}}`
}
